const q = ($json.question || '').toLowerCase();

const TURKISH_MONTHS = {
  'ocak': '01', 'subat': '02', 'mart': '03', 'nisan': '04',
  'mayis': '05', 'haziran': '06', 'temmuz': '07', 'agustos': '08',
  'eylul': '09', 'ekim': '10', 'kasim': '11', 'aralik': '12'
};

let dateFrom = '2026-09-02';
let dateTo = '2026-09-02';
let dateDesc = 'Bugün (2026-09-02)';
let sqlClause = "day = '2026-09-02'";
let requiresClarification = false;
let clarificationQuestion = null;

function normTr(str) {
  return str.replace(/İ/g, 'i').replace(/I/g, 'i').replace(/ı/g, 'i').replace(/ç/g, 'c').replace(/Ç/g, 'c').replace(/ğ/g, 'g').replace(/Ğ/g, 'g').replace(/ö/g, 'o').replace(/Ö/g, 'o').replace(/ş/g, 's').replace(/Ş/g, 's').replace(/ü/g, 'u').replace(/Ü/g, 'u').toLowerCase().trim();
}
const qNorm = normTr(q);

const ddmmyyyyMatch = q.match(/\b(0?[1-9]|[12][0-9]|3[01])[./-](0?[1-9]|1[0-2])[./-](202\d)\b/);
if (ddmmyyyyMatch) {
  const day = String(ddmmyyyyMatch[1]).padStart(2, '0');
  const month = String(ddmmyyyyMatch[2]).padStart(2, '0');
  const year = ddmmyyyyMatch[3];
  const iso = `${year}-${month}-${day}`;
  dateFrom = iso; dateTo = iso; dateDesc = `${day}.${month}.${year}`; sqlClause = `day = '${iso}'`;
} else if (qNorm.includes('bugun')) {
  dateFrom = '2026-09-02'; dateTo = '2026-09-02'; dateDesc = 'Bugün (2026-09-02)'; sqlClause = "day = '2026-09-02'";
} else if (qNorm.includes('dun')) {
  dateFrom = '2026-09-01'; dateTo = '2026-09-01'; dateDesc = 'Dün (2026-09-01)'; sqlClause = "day = '2026-09-01'";
} else if (qNorm.includes('yarin')) {
  dateFrom = '2026-09-03'; dateTo = '2026-09-03'; dateDesc = 'Yarın (2026-09-03)'; sqlClause = "day = '2026-09-03'";
} else if (qNorm.includes('bu hafta')) {
  dateFrom = '2026-08-31'; dateTo = '2026-09-06'; dateDesc = 'Bu Hafta (2026-08-31 / 2026-09-06)'; sqlClause = "day >= '2026-08-31' AND day <= '2026-09-06'";
} else if (qNorm.includes('gecen hafta')) {
  dateFrom = '2026-08-24'; dateTo = '2026-08-30'; dateDesc = 'Geçen Hafta (2026-08-24 / 2026-08-30)'; sqlClause = "day >= '2026-08-24' AND day <= '2026-08-30'";
} else if (qNorm.includes('son 7 gun') || qNorm.includes('son yedi gun')) {
  dateFrom = '2026-08-26'; dateTo = '2026-09-02'; dateDesc = 'Son 7 Gün (2026-08-26 - 2026-09-02)'; sqlClause = "day >= '2026-08-26' AND day <= '2026-09-02'";
} else {
  for (const [mName, mCode] of Object.entries(TURKISH_MONTHS)) {
    const monthRegex = new RegExp(`\\b(0?[1-9]|[12][0-9]|3[01])\\s+${mName}(?:\\s+(202\\d))?\\b`, 'i');
    const mMatch = qNorm.match(monthRegex);
    if (mMatch) {
      const day = String(mMatch[1]).padStart(2, '0');
      const year = mMatch[2] || '2026';
      const iso = `${year}-${mCode}-${day}`;
      dateFrom = iso; dateTo = iso; dateDesc = `${mMatch[1]} ${mName} ${year}`; sqlClause = `day = '${iso}'`;
      break;
    }
  }
}

// Fast Deterministic SQL
let fastSql = null;
if (qNorm.includes('en cok gec kalan') || qNorm.includes('en fazla geciken') || (qNorm.includes('en cok') && qNorm.includes('geciken'))) {
  fastSql = `SELECT employee_no, full_name, department, SUM(late_minutes) AS total_late_minutes, COUNT(*) AS late_days_count FROM attendance.daily_summary WHERE ${sqlClause} AND status = 'LATE' GROUP BY employee_no, full_name, department ORDER BY total_late_minutes DESC LIMIT 10;`;
} else if (qNorm.includes('toplam gecikme') || (qNorm.includes('gecikme suresi') && qNorm.includes('toplam'))) {
  fastSql = `SELECT SUM(late_minutes) AS total_late_minutes, COUNT(CASE WHEN status = 'LATE' THEN 1 END) AS late_occurrences FROM attendance.daily_summary WHERE ${sqlClause};`;
} else if (qNorm.includes('zamaninda') && (qNorm.includes('sayisi') || qNorm.includes('kac'))) {
  fastSql = `SELECT COUNT(*) AS on_time_count FROM attendance.daily_summary WHERE ${sqlClause} AND status = 'ON_TIME';`;
} else if (qNorm.includes('gec kaldi') || (qNorm.includes('gec kalan') && !qNorm.includes('en cok'))) {
  fastSql = `SELECT employee_no, full_name, department, shift_name, late_minutes FROM attendance.daily_summary WHERE ${sqlClause} AND status = 'LATE' ORDER BY late_minutes DESC LIMIT 100;`;
} else if (qNorm.includes('izinli olan') || (qNorm.includes('izin') && qNorm.includes('kimler'))) {
  fastSql = `SELECT employee_no, full_name, department, exception_types, day FROM attendance.daily_summary WHERE ${sqlClause} AND status = 'ON_LEAVE' ORDER BY employee_no LIMIT 100;`;
} else if (qNorm.includes('uzaktan calisan')) {
  fastSql = `SELECT employee_no, full_name, department, day FROM attendance.daily_summary WHERE ${sqlClause} AND status = 'REMOTE' ORDER BY employee_no LIMIT 100;`;
} else {
  fastSql = `SELECT employee_no, full_name, department, shift_name, late_minutes FROM attendance.daily_summary WHERE ${sqlClause} AND status = 'LATE' ORDER BY late_minutes DESC LIMIT 100;`;
}

return [{
  json: {
    question: $json.question,
    session_id: $json.session_id || 'sql_session',
    request_id: $json.request_id || ('req_' + Date.now()),
    normalizedDate: sqlClause,
    dateDesc,
    sql: fastSql,
    requiresClarification,
    clarificationQuestion
  }
}];

const prev = $('Normalize Date and Entities').first().json;
let rawSql = (prev.sql || '').trim();

const forbidden = /\b(INSERT|UPDATE|DELETE|MERGE|DROP|ALTER|CREATE|TRUNCATE|COPY|CALL|GRANT|REVOKE|VACUUM|EXECUTE|PREPARE|DO)\b/i;
let isSafe = true;
let reason = '';

if (!/^\s*(WITH\s+[\s\S]+?\s+)?SELECT\s+/i.test(rawSql)) {
  isSafe = false;
  reason = 'Sorgu sadece SELECT ile başlamalıdır.';
} else if (forbidden.test(rawSql)) {
  isSafe = false;
  reason = 'Yasaklı DDL/DML anahtar kelimesi tespit edildi.';
} else if (rawSql.replace(/;+\s*$/, '').includes(';')) {
  isSafe = false;
  reason = 'Çoklu statement yasaktır.';
} else if (rawSql.includes('--') || rawSql.includes('/*')) {
  isSafe = false;
  reason = 'SQL yorum satırı yasaktır.';
}

if (isSafe && !rawSql.toLowerCase().includes('limit') && !rawSql.toLowerCase().includes('count(') && !rawSql.toLowerCase().includes('sum(') && !rawSql.toLowerCase().includes('avg(')) {
  rawSql = rawSql.replace(/;*$/, ' LIMIT 100;');
}

return [{
  json: {
    ...prev,
    sql: rawSql,
    isSafe,
    safetyReason: reason
  }
}];

const items = $input.all().map(i => i.json);
const prev = $('SQL Safety Guard').first().json;

if (items.length === 0) {
  return [{
    json: {
      ...prev,
      status: 'SUCCESS',
      rowCount: 0,
      answer: `**Sonuç Özeti (${prev.dateDesc}):**\nKriterlere uygun herhangi bir kayıt bulunamadı.\n\n*(Yürütülen SQL: \`${prev.sql}\`)*`,
      rows: []
    }
  }];
}

if (items.length === 1 && (items[0].on_time_count !== undefined || items[0].total_late_minutes !== undefined)) {
  const r = items[0];
  let msg = '';
  if (r.on_time_count !== undefined) {
    msg = `**Sonuç Özeti (${prev.dateDesc}):**\nBelirtilen tarihte toplam **${r.on_time_count}** çalışan zamanında gelmiştir.\n\n*(Yürütülen SQL: \`${prev.sql}\`)*`;
  } else if (r.total_late_minutes !== undefined) {
    msg = `**Sonuç Özeti (${prev.dateDesc}):**\nToplam gecikme süresi **${r.total_late_minutes || 0} dakika** (${r.late_occurrences || 0} vaka) olarak hesaplanmıştır.\n\n*(Yürütülen SQL: \`${prev.sql}\`)*`;
  }
  return [{
    json: {
      ...prev,
      status: 'SUCCESS',
      intent: 'ATTENDANCE_SQL',
      title: 'Devam Bilgisi',
      rowCount: 1,
      answer: msg,
      rows: items
    }
  }];
}

let summary = `**Sonuç Özeti (${prev.dateDesc}):**\nToplam **${items.length}** kayıt listelendi.\n\n`;
summary += '| Sicil | Ad Soyad | Departman | Durum | Detay |\n| :--- | :--- | :--- | :---: | :--- |\n';

for (const r of items.slice(0, 8)) {
  const empNo = r.employee_no || '-';
  const name = r.full_name || '-';
  const dept = r.department || '-';
  const status = r.status || (r.total_late_minutes ? 'LATE' : '-');
  let detail = '';
  if (r.late_minutes && r.late_minutes > 0) detail = `${r.late_minutes} dk geç`;
  else if (r.total_late_minutes) detail = `Toplam ${r.total_late_minutes} dk (${r.late_days_count} gün)`;
  else if (r.worked_minutes) detail = `${r.worked_minutes} dk çalışma`;
  else if (r.exception_types) detail = r.exception_types;
  else if (r.missing_checkout) detail = 'Çıkış basılmadı';
  else detail = r.shift_name || '-';

  summary += `| ${empNo} | ${name} | ${dept} | **${status}** | ${detail} |\n`;
}

if (items.length > 8) {
  summary += `\n*... ve ${items.length - 8} kayıt daha.*`;
}
summary += `\n\n*(Yürütülen SQL: \`${prev.sql}\`)*`;

return [{
  json: {
    ...prev,
    status: 'SUCCESS',
    intent: 'ATTENDANCE_SQL',
    title: 'Devam Bilgisi',
    rowCount: items.length,
    answer: summary,
    rows: items
  }
}];
